#include <Arduino.h>

// おすすめのD3ピン（GPIO 3）を指定します
#define TARGET_PIN 3 

void setup() {
  // 【最重要】これがないと、再び2秒おきの通知ループが始まってしまいます！
  Serial.begin(115200);
  delay(1000); 

  // 指定したピンを出力（電気を出す設定）にします
  pinMode(TARGET_PIN, OUTPUT);
}

void loop() {
  // LEDを点灯（電気をON）
  digitalWrite(TARGET_PIN, HIGH);
  delay(500); // 0.5秒待つ

  // LEDを消灯（電気をOFF）
  digitalWrite(TARGET_PIN, LOW);
  delay(500); // 0.5秒待つ
}
